#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct FederatedCommonsCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub mode:String,pub scale:String,pub request_id:String,pub purpose:String,pub disposition:String,pub peer_order:Vec<String>,pub admitted_order:Vec<String>,pub denied_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub revoked_order:Vec<String>,pub negative_evidence_order:Vec<String>,pub capability_order:Vec<String>,pub localization:String,pub replay_identity:ContentHash,pub federation_digest:ContentHash,pub artifact:FederatedCommonsArtifact4,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
